GRANT SELECT ON TABLE public.shipper_reputation_view TO asoc_app;
GRANT SELECT ON TABLE public.shipper_spend_view TO asoc_app;
GRANT SELECT,INSERT ON TABLE public.users TO asoc_app;
GRANT SELECT ON TABLE public.verification_reviews TO asoc_app;
